// app-cve.js — page module extracted from app.js (buildless, classic script;
// all symbols remain global like the rest of the client JS).
// Generated by refactor extraction. Do not add a build step.

// v7.4.6 (#57): which fix status the CVE page is filtered to ('' = all). The tiles under the severity
// counts say how many findings are in each, and clicking one filters the host table and the host view.
let cveFixFilter = '';
const _CVE_FIX_NAME = {fixable: 'Fixable now', reboot: 'Reboot to apply', newer_release: 'Newer release only', none: 'No fix yet', pro: 'Needs Ubuntu Pro', unchecked: 'Not checked'};

// The tile a finding is counted in. The same rule as cve_fixes.summarize on the server: a status of
// "unknown", or none at all (a finding scanned before 7.4.6), counts by its fixed version.
function _cveFixKey(f) {
  if (f.fix_status === 'fixed') return 'fixable';
  if (f.fix_status === 'reboot' || f.fix_status === 'newer_release' || f.fix_status === 'none' || f.fix_status === 'pro') return f.fix_status;
  const fv = f.fixed_version;       // text that is not blank, as the server reads it; a number counts as its text
  return (typeof fv === 'string' && fv.trim()) || (typeof fv === 'number' && fv) ? 'fixable' : 'unchecked';
}

function _markCveFixTiles() {
  document.querySelectorAll('#cve-fix-row .stat-card').forEach(el => {
    el.setAttribute('aria-pressed', el.dataset.arg === cveFixFilter ? 'true' : 'false');
  });
}

function _renderCveFixTiles(fix) {
  fix = fix || {};
  for (const key of Object.keys(_CVE_FIX_NAME)) animateStat('cve-fix-' + key, fix[key] || 0);
  _markCveFixTiles();
}

function _renderCveHostTable() {
  if (!cveReportData) return;
  const all = cveReportData.devices || [];
  const rows = cveFixFilter ? all.filter(d => ((d.fix || {})[cveFixFilter] || 0) > 0) : all;
  tableCtl.render('cves', rows);
  if (cveFixFilter && !rows.length) {
    document.getElementById('cve-tbody').innerHTML = '<tr><td colspan="11" class="empty-state">No CVE rows match the filter.</td></tr>';
  }
}

function setCveFixFilter(key) {
  cveFixFilter = (cveFixFilter === key) ? '' : String(key);
  _markCveFixTiles();
  _renderCveHostTable();
}

function clearCveFixFilter(devId, devName) {
  cveFixFilter = '';
  _markCveFixTiles();
  _renderCveHostTable();
  openDeviceCVE(devId, devName);
}

// What a finding says about its fix. A fixed version is the one for this host's own release; a finding
// that is fixed only in a newer release, or in none, says so and names no version to install.
function _cveFixHtml(f) {
  if (f.fix_status === 'reboot') {
    // 8.0.2: an installed kernel that does not run holds the fix; nothing to install, a reboot starts it
    const into = typeof f.reboot_to === 'string' && f.reboot_to ? ` <span class="c-muted">(<span data-no-i18n="">${escHtml(f.reboot_to)}</span>)</span>` : '';
    return ` — <span class="c-green">Fixed by an installed kernel, reboot to apply</span>${into}`;
  }
  if (f.fix_status === 'newer_release' || f.fix_status === 'pro') {
    // 8.0.1: "pro" is a fix that is in Ubuntu Pro only, for the host's own release
    const where = Object.entries(f.fixed_elsewhere || {}).slice(0, 2)
      .map(([eco, v]) => `${escHtml(eco)} ${escHtml(v)}`).join(', ');
    return ` — <span class="c-muted">${f.fix_status === 'pro' ? 'Fixed with Ubuntu Pro' : 'Fixed in a newer release'}</span>${where ? ` <span class="c-muted">(${where})</span>` : ''}`;
  }
  if (f.fix_status === 'none') return ' — <span class="c-muted">No fix yet</span>';
  return f.fixed_version ? ` → fixed in <span class="c-green">${escHtml(f.fixed_version)}</span>` : '';
}

function renderCveSeverityRow(severities, current) {
  const row = document.getElementById('cfg-cve-severity-row');
  if (!row) return;
  row.innerHTML = severities.map(s => {
    const checked = current.includes(s) ? 'checked' : '';
    return `<label class="isl-339"><input type="checkbox" class="cfg-cve-sev isl-340" value="${escHtml(s)}" ${checked}>${escHtml(s)}</label>`;
  }).join('');
}

// v6.2.3: exposure-weighted CVE ranking — hosts ordered by exploitability.
async function openCveExposure() {
  const el = document.getElementById('cve-exp-body');
  if (el) el.innerHTML = _skeletonBlock(4);
  openModal('cve-exposure-modal');
  const d = await api('GET', '/cve/exposure-ranked').catch(() => null);
  if (!el) return;
  if (!d || d.error) { _errorState(el, openCveExposure, {msg: (d && d.error) || 'Failed to load'}); return; }
  const hosts = d.hosts || [];
  if (!hosts.length) { el.innerHTML = '<div class="empty-state">No hosts with open CVEs.</div>'; return; }
  const trs = hosts.map((h, i) => {
    const exp = h.world_exposed
      ? `<span class="badge badge-crit" title="${escAttr((h.exposed_ports || []).join(', '))}">EXPOSED</span>`
      : '<span class="c-muted fs-12">internal</span>';
    const crit = h.criticality
      ? `<span class="c-muted fs-12">${escHtml(h.criticality)}</span>`
      : '<span class="hint">—</span>';
    return `<tr><td class="ta-center hint">${i + 1}</td>`
      + `<td class="fw-500">${escHtml(h.device_name)}</td>`
      + `<td>${exp}</td>`
      + `<td class="ta-center">${crit}</td>`
      + `<td class="ta-center c-red">${h.critical}</td>`
      + `<td class="ta-center">${h.high}</td>`
      + `<td class="ta-center hint">${h.fixable} fixable</td>`
      + `<td class="ta-center fw-500">${h.score}</td></tr>`;
  }).join('');
  el.innerHTML =
    `<div class="hint mb-8">${plural(d.exposed_with_critical, 'world-exposed host', 'world-exposed hosts')} carry a critical CVE — patch these first. Score is scaled by each asset's CMDB business criticality.</div>`
    + `<div class="scrollable-table-wrap audit-scroll"><table><thead><tr><th>#</th><th>Host</th><th>Reach</th><th>Crit·ality</th><th>Crit</th><th>High</th><th>Fixable</th><th>Score</th></tr></thead><tbody>${trs}</tbody></table></div>`;
}

async function loadCVEReport() {
  _registerCveTable();
  const tbody = document.getElementById('cve-tbody');
  tbody.innerHTML = _skeletonRows(11, 5);
  const data = await api('GET', '/cve/findings');
  if (!data) return;
  if (data.error || !data.summary) {
    _errorState(tbody, loadCVEReport, {msg: 'Failed to load: ' + (data.error || 'no answer'), colspan: 11});
    return;
  }
  cveReportData = data;
  // v6.3.0 (UX wave 10): stats animate old→new with a fading delta arrow.
  animateStat('cve-stat-critical', data.summary.critical);
  animateStat('cve-stat-high', data.summary.high);
  animateStat('cve-stat-medium', data.summary.medium);
  animateStat('cve-stat-low', data.summary.low);
  animateStat('cve-stat-devices', data.summary.devices_scanned);
  _renderKevFeedStatus(data.kev_feed);
  _renderCveFixTiles(data.summary.fix);
  const countNote = document.getElementById('cve-count-note');
  if (countNote) countNote.hidden = data.counting !== 'fixable_only';
  // 8.0.1: what the scans counted per package and did not list one by one, for the fleet
  const rollNote = document.getElementById('cve-rollup-note'), rolled = typeof data.summary.rollup === 'number' ? data.summary.rollup : 0;
  if (rollNote) { rollNote.hidden = !rolled; rollNote.lastElementChild.textContent = rolled; }
  // 8.0.2: hosts that were accepted are left out of every number above; the note says how many, and how many findings that is
  const whole = v => (typeof v === 'number' && isFinite(v) && v >= 0) ? Math.floor(v) : 0;
  const accNote = document.getElementById('cve-accepted-note'), accHosts = whole(data.summary.accepted_hosts);
  if (accNote) {
    accNote.hidden = !accHosts;
    document.getElementById('cve-accepted-hosts').textContent = accHosts;
    document.getElementById('cve-accepted-findings').textContent = whole(data.summary.accepted_findings);
  }
  _renderCveCoveredNote(data.summary.covered, data.summary.most_not_checked);
  _renderCveHostTable();
  loadCveCampaigns();
}

// 8.0.2: how many of the packages the hosts listed their scans checked, and the hosts with the most that they did not
// (cve_scanner.entry_package_coverage per host, summed by handle_cve_findings). Shown when something was not checked:
// a fleet with no finding is clean only in the packages that could be checked. The totals hold the hosts whose last scan
// states what it checked. A scanned host whose scan is from before that is in neither number, and an upgrade starts no
// scan, so the note says how many they are, and with none of the others it has no totals to print.
function _renderCveCoveredNote(total, hosts) {
  const note = document.getElementById('cve-covered-note');
  if (!note) return;
  const num = v => typeof v === 'number' && isFinite(v) && v >= 0 ? Math.floor(v) : 0;
  const fmt = v => num(v).toLocaleString(_localeTag());
  const sums = total && typeof total === 'object' ? total : {};
  const missed = num(sums.not_checked), listed = num(sums.listed), unstated = num(sums.hosts_unstated);
  note.hidden = !missed && !unstated;
  if (note.hidden) return;
  document.getElementById('cve-covered-line').hidden = !listed;
  document.getElementById('cve-covered-total').textContent = `${fmt(sums.checked)} / ${fmt(listed)}`;
  document.getElementById('cve-covered-missed').textContent = fmt(missed);
  const reasons = sums.reasons && typeof sums.reasons === 'object' ? sums.reasons : {};
  document.getElementById('cve-covered-reasons').innerHTML = Object.keys(_CVE_NOT_CHECKED).filter(r => num(reasons[r]) > 0)
    .map(r => `<span>${escHtml(_CVE_NOT_CHECKED[r])}</span> <strong>${fmt(reasons[r])}</strong>`).join(' · ');
  document.getElementById('cve-covered-unstated').hidden = !unstated;
  document.getElementById('cve-covered-unstated-n').textContent = fmt(unstated);
  const top = (Array.isArray(hosts) ? hosts : []).filter(h => h && typeof h.device_id === 'string' && num(h.not_checked) > 0).slice(0, 5);
  document.getElementById('cve-covered-hosts').innerHTML = top.length
    ? `<span>Most not checked:</span> ` + top.map(h => `<button class="btn-icon cell-sm" data-action="openDeviceCVE" data-arg="${escAttr(h.device_id)}" data-arg2="${escAttr(String(h.name || h.device_id))}"><span data-no-i18n="">${escHtml(String(h.name || h.device_id))}</span> <span>${fmt(h.not_checked)} / ${fmt(h.listed)}</span></button>`).join(' ')
    : '';
}

// W2-35: CVE remediation campaigns.
// W6-34: container-image CVEs from trivy, grouped by image.
async function loadImageCves() {
  const box = document.getElementById('image-cve-list');
  if (!box) return;
  const r = await api('GET', '/image-cves').catch(() => null);
  if (!r) { _errorState(box, loadImageCves); return; }
  const imgs = r.images || [];
  if (!imgs.length) {
    // v6.1.2: distinguish "on, but no host has reported yet" from "off" and
    // from "on and clean" — all three used to render the same dead-end text,
    // which is how a broken scan looked exactly like an idle one.
    if (!r.enabled) {
      box.innerHTML = '<div class="meta-sm-nm">Image scanning is off — enable it in Settings → Security.</div>';
    } else if (r.scanned) {
      box.innerHTML = '<div class="meta-sm-nm">No image vulnerabilities found on the hosts that have reported.</div>';
    } else {
      box.innerHTML = '<div class="meta-sm-nm">No host has reported an image scan yet. '
        + 'Trivy runs every ~24h — use <strong>Scan now</strong> to trigger it immediately '
        + 'on every host running containers.</div>';
    }
    return;
  }
  box.innerHTML = imgs.map(g => {
    const hosts = g.hosts.map(h => escHtml(h.name)).join(', ');
    const top = (g.top || []).slice(0, 8).map(v =>
      `<tr><td class="ff-mono fs-12">${escHtml(v.id)}</td><td class="fs-12">${escHtml(v.pkg)}</td>`
      + `<td class="fs-12 ${v.severity === 'CRITICAL' ? 'c-red' : 'c-amber'}">${escHtml(v.severity)}</td>`
      + `<td class="fs-12">${escHtml(v.installed || '')}${v.fixed ? ' → ' + escHtml(v.fixed) : ''}</td></tr>`).join('');
    return `<div class="dash-card mb-8"><div class="row-8-center"><span class="fw-500 ff-mono">${escHtml(g.image)}</span>`
      + `<span class="patch-badge crit fs-11">${g.critical} crit</span>`
      + `<span class="patch-badge fs-11">${g.high} high</span>`
      + `<span class="patch-badge fs-11">${g.medium} med</span></div>`
      + `<div class="hint mt-4">on: ${hosts}</div>`
      + (top ? `<div class="table-card scrollable-table-wrap audit-scroll mt-6"><table><thead><tr><th>CVE</th><th>Package</th><th>Severity</th><th>Version</th></tr></thead><tbody>${top}</tbody></table></div>` : '')
      + '</div>';
  }).join('');
}

// v6.1.2: actually TRIGGER a trivy scan. "Refresh" only ever re-fetched the
// stored results — there was no way to make the scan run, so a host with trivy
// installed could sit at an empty page indefinitely (the agent's only other
// trigger was a poll-count cadence that resets on every agent restart).
async function scanImageCves() {
  const r = await api('POST', '/image-cves/scan', {});
  if (r && r.ok) {
    // v6.4.3: the server drops non-Linux hosts (trivy is driven by the Linux
    // agent alone) and names them in `message`. A batch where EVERY target was
    // dropped still returned ok:true, so a green "success" toast carried a
    // sentence explaining that nothing had been queued — the sibling backup
    // and host-config fixes in the same release both warn in this case.
    const nothingQueued = !r.queued;
    toast(r.message || 'Image scan queued',
          nothingQueued && (r.skipped_unsupported || []).length ? 'warning'
          : nothingQueued ? 'info' : 'success');
  } else {
    toast((r && r.error) || 'Failed to queue image scan', 'error');
  }
}

async function loadCveCampaigns() {
  const box = document.getElementById('cve-campaigns-list');
  if (!box) return;
  const r = await api('GET', '/cve/campaigns');
  if (!r || !r.ok) return;
  const camps = r.campaigns || [];
  if (!camps.length) { box.innerHTML = '<div class="meta-sm-nm">No campaigns yet. Fill in the form below and click "Create campaign".</div>'; return; }
  box.innerHTML = camps.map(c => {
    const scope = (c.cve_ids && c.cve_ids.length) ? `${c.cve_ids.length} CVEs`
      : [(c.severities || []).join('/'), c.kev_only ? 'KEV' : ''].filter(Boolean).join(' · ') || 'all';
    const spark = renderSparkline((c.samples || []).map(s => s.affected), { width: 80, height: 18 });
    const done = c.completed_at ? ' <span class="patch-badge ok fs-11">completed</span>' : '';
    const tgt = c.target_date ? ` · due ${escHtml(c.target_date)}` : '';
    return `<div class="dash-card mb-8"><div class="row-6-center">`
      + `<span class="fw-500 fs-13 ellipsis flex-1">${escHtml(c.name)}${done} <span class="meta-sm-nm">${escHtml(c.owner || '')}${tgt}</span></span>`
      + `<span class="fs-13" title="Affected hosts / matching findings">${plural(c.affected_hosts, 'host', 'hosts')}, ${c.finding_count} findings</span>`
      + `<span title="Affected-host burn-down">${spark}</span>`
      + `<button class="btn-icon c-danger-outline cell-sm" data-action="deleteCveCampaign" data-arg="${escAttr(c.id)}">Delete</button>`
      + `</div><div class="meta-sm-nm mt-4">Scope: ${escHtml(scope)}</div></div>`;
  }).join('');
}
async function createCveCampaign() {
  const name = (document.getElementById('camp-name')?.value || '').trim();
  if (!name) { toast('Campaign name required', 'error', {transient: true}); return; }
  const sevs = [];
  if (document.getElementById('camp-sev-critical')?.checked) sevs.push('critical');
  if (document.getElementById('camp-sev-high')?.checked) sevs.push('high');
  const cveIds = (document.getElementById('camp-cves')?.value || '')
    .split(/[\s,]+/).map(s => s.trim()).filter(Boolean);
  const body = {
    name,
    owner: (document.getElementById('camp-owner')?.value || '').trim(),
    target_date: document.getElementById('camp-target')?.value || '',
    severities: sevs,
    kev_only: !!document.getElementById('camp-kev')?.checked,
    cve_ids: cveIds,
  };
  const r = await api('POST', '/cve/campaigns', body);
  if (r && r.ok) {
    toast('Campaign created', 'success');
    ['camp-name', 'camp-owner', 'camp-cves'].forEach(id => { const e = document.getElementById(id); if (e) e.value = ''; });
    loadCveCampaigns();
  } else failToast(r);
}
async function deleteCveCampaign(cid) {
  // v6.3.0 (UX): undoable deferred delete — a campaign is a RemotePower-local
  // tracking record, so Undo beats an irreversible confirm.
  undoableDelete({
    label: 'Campaign deleted',
    hide: () => _hideRowByAction('deleteCveCampaign', cid),
    commit: () => api('DELETE', '/cve/campaigns/' + encodeURIComponent(cid)),
    undo: () => loadCveCampaigns(),
    after: () => loadCveCampaigns(),
  });
}

function _renderKevFeedStatus(f) {
  const el = document.getElementById('cve-kev-feed-text');
  if (!el) return;
  if (!f) { el.textContent = ''; return; }
  if (f.kev_error) { el.innerHTML = `<span class="c-red">KEV feed failed: ${escHtml(f.kev_error)}</span> — KEV flags unavailable until it loads.`; return; }
  if (!f.kev_count) { el.textContent = 'KEV feed not loaded yet (refreshes daily, or click below). KEV stays 0 until then.'; return; }
  const when = f.last_checked ? timeAgo(f.last_checked) : 'unknown';
  el.textContent = `KEV feed: ${f.kev_count.toLocaleString(_localeTag())} known-exploited CVEs loaded (updated ${when}). A 0 here means none of that host's CVEs are on CISA's KEV list.`;
}

async function refreshCveFeeds() {
  toast('Refreshing KEV/EPSS feeds…', 'info');
  const r = await api('POST', '/cve/refresh-feeds', {}).catch(() => null);
  if (r?.ok) {
    toast(`KEV feed: ${r.kev_count} CVEs${r.kev_error ? ' (error: ' + r.kev_error + ')' : ''}`, r.kev_error ? 'error' : 'success');
    loadCVEReport();
  } else toast(r?.error || 'Feed refresh failed', 'error');
}

async function triggerCVEScan(devId, btn) {
  // v4.1.0: the scan now runs in a detached background process and returns
  // immediately ("Queued"), so the page never blocks. We poll scan-status for
  // progress and refresh the report when it finishes.
  // v5.0.0 fix: the "Scan all" button is wired via data-action-btn, which calls
  // us with the BUTTON ELEMENT as the first arg (per-device callers pass a
  // string id). Normalise so we never POST the element as device_id — that
  // serialised to {} and the server rejected it with 400 Bad Request.
  if (devId && typeof devId === 'object') { btn = devId; devId = null; }
  const origText = btn ? btn.innerHTML : '';   // innerHTML: preserve the SVG icon on restore
  if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
  const r = await api('POST', '/cve/scan', devId ? { device_id: devId } : {});
  if (!r || !(r.queued || r.ok)) {
    const msg = (r && r.error) || 'Could not queue the scan';
    toast(r && r.status && r.status.running ? 'A scan is already running' : msg, 'error');
    if (btn) { btn.disabled = false; btn.innerHTML = origText; }
    return;
  }
  toast(`Scan started${r.total ? ` (${r.total} host${r.total === 1 ? '' : 's'})` : ''} — running in the background.`, 'info');
  // Poll progress with a NON-OVERLAPPING self-scheduling loop: the next request
  // is queued only AFTER the previous one resolves. A plain setInterval fires
  // every 2s regardless, so a slow/blocked server piles up hundreds of pending
  // fetches and Firefox flags the page as "slowing the browser". Bounded by a
  // wall-clock cap so a stuck scan can't poll forever.
  let ticks = 0;
  const MAX_TICKS = 600;
  const finish = (st) => {
    if (btn) {
      btn.disabled = false;
      btn.style.color = _textInk((st && st.errors) ? 'var(--red-ink)' : 'var(--green-ink)');
      setTimeout(() => { if (btn.isConnected) { btn.innerHTML = origText; btn.style.color = ''; } }, 4000);
    }
    if (st && !st.running) {
      toast(`Scan complete: ${st.scanned || 0} scanned, ${st.skipped || 0} skipped, ${st.errors || 0} errors`,
            st.errors ? 'error' : 'success',
            Array.isArray(st.error_notes) && st.error_notes.length ? { detail: st.error_notes.filter(n => typeof n === 'string').join(' | '), duration: 15000 } : {});
      loadCVEReport();
    }
  };
  const tick = async () => {
    ticks++;
    const st = await api('GET', '/cve/scan-status').catch(() => null);
    if (st && btn && st.total) btn.innerHTML = st.running
      ? `${_progressRing(st.done / st.total)} Scanning ${st.done}/${st.total}…`
      : 'Done';   // v6.3.0 (wave 10): real-fraction progress ring
    if (!st || !st.running || ticks > MAX_TICKS) { finish(st); return; }
    setTimeout(tick, 2000);              // schedule the next poll only now
  };
  setTimeout(tick, 2000);
}

// 8.0.1: what a scan of this host leaves out. The server sends the word (cve_scanner.coverage), the page
// holds the sentence, so it is translated like any other text.
const _CVE_COVERAGE = {
  no_release: 'The Ubuntu release this host is based on is not known, so a package built from a source package with another name, such as libc6, libssl3 or openssh-server, is not checked.',
  needs_agent: 'The agent of this host does not report source packages, so a package built from a source package with another name is not checked. Update the agent, then send the package list again.',
  no_matcher: 'The software of this host is listed, but no vulnerability database is matched against it, so nothing on it is checked. No findings here does not mean no vulnerabilities.',
};

function _cveCoverageHtml(data) {
  let html = '';
  if (typeof data.coverage === 'string' && Object.prototype.hasOwnProperty.call(_CVE_COVERAGE, data.coverage)) {
    html += `<div class="hint mb-8" data-cve-coverage="${escAttr(data.coverage)}"><span>${escHtml(_CVE_COVERAGE[data.coverage])}</span></div>`;
  }
  if (Array.isArray(data.cut) && data.cut.length) {
    html += `<div class="hint mb-8" data-cve-cut=""><span>The advisory list of these packages was longer than a scan reads, so it is cut:</span> <span class="mono-12">${escHtml(data.cut.join(', '))}</span></div>`;
  }
  return html;
}

// 8.0.1: what a scan counted per package and did not list one by one (cve_fixes.split on the server): a finding
// no update for the host's release clears, unless it is critical, high or known to be exploited, and what did not
// fit under the ceiling of a host or a package. A package name is data, so the rows are not translated.
function _cveRollupHtml(r) {
  if (!r || typeof r.total !== 'number' || !(r.total > 0)) return '';
  // a number or nothing, a name or nothing: an object where one belongs is not printed and not converted
  const num = v => typeof v === 'number' && isFinite(v) && v > 0 ? v : 0;
  const n = (o, k) => num(o && o[k]);
  const txt = v => typeof v === 'string' ? v : '';
  const rows = (Array.isArray(r.packages) ? r.packages : []).map(p => !p ? ''
    : `<tr><td class="mono-12">${escHtml(txt(p.name))}</td><td class="mono-12">${escHtml(txt(p.version))}</td><td class="ta-center">${num(p.count)}</td></tr>`).join('');
  const more = n(r.more, 'packages') > 0 ? `<div class="hint mt-6"><span>Packages not shown:</span> <span>${n(r.more, 'packages')}</span></div>` : '';
  const sev = n(r.severity, 'critical') + n(r.severity, 'high') > 0
    ? `<div class="hint mt-6"><span>Of these, critical or high:</span> <span>${n(r.severity, 'critical') + n(r.severity, 'high')}</span></div>` : '';
  const fixable = n(r.fix, 'fixable') > 0 ? `<div class="hint mt-6"><span>Of these, cleared by an update:</span> <span>${n(r.fix, 'fixable')}</span></div>` : '';
  // 8.0.2: an installed kernel that is not running already holds the fix of these, so nothing is left to install: a reboot
  // applies them. A kernel has the most findings of any package, so this is the line of the host the status is for.
  const reboot = n(r.fix, 'reboot') > 0 ? `<div class="hint mt-6"><span>Of these, fixed by an installed kernel, reboot to apply:</span> <span>${n(r.fix, 'reboot')}</span></div>` : '';
  // the tile "Needs Ubuntu Pro" counts the listed ones; on a release past its standard support most are here
  const pro = n(r.fix, 'pro') > 0 ? `<div class="hint mt-6"><span>Of these, fixed with Ubuntu Pro:</span> <span>${n(r.fix, 'pro')}</span></div>` : '';
  return `<details class="mb-8" data-cve-rollup=""><summary class="hint pointer"><span>Known vulnerabilities counted per package and not listed one by one:</span> <strong>${r.total}</strong></summary>`
    + sev + fixable + reboot + pro
    + (rows ? `<div class="scrollable-table-wrap audit-scroll mt-6"><table><thead><tr><th>Package</th><th>Installed</th><th class="ta-center">Count</th></tr></thead><tbody data-no-i18n="">${rows}</tbody></table></div>` : '')
    + more + '</details>';
}

// 8.0.2: which of the packages a host listed a scan checked, and why it did not check the others (the server
// builds the block in cve_scanner.package_coverage and sends the reason as a word, cve_fixes.REASONS). The page
// holds the sentences, so they are translated. A package name is data, so the rows are not.
const _CVE_NOT_CHECKED = {
  no_source: 'No source name',
  no_matcher: 'No matcher for the package manager',
  no_release: 'Release not known',
  ceiling: 'Past the limit of packages a scan reads',
  unanswered: 'Not answered in full by the data source',
};

function _cveCoveredHtml(c) {
  if (!c || typeof c !== 'object') return '';
  // a number or nothing: an object where one belongs is not printed and not converted
  const num = v => typeof v === 'number' && isFinite(v) && v >= 0 ? Math.floor(v) : 0;
  const fmt = v => Number(num(v)).toLocaleString(_localeTag());
  const listed = num(c.listed), checked = num(c.checked), missed = num(c.not_checked);
  if (!listed && !missed) return '';
  const label = r => Object.prototype.hasOwnProperty.call(_CVE_NOT_CHECKED, r) ? _CVE_NOT_CHECKED[r] : '';
  const head = `<span>Packages checked:</span> <strong>${fmt(checked)} / ${fmt(listed)}</strong>`
    + (missed ? ` · <span>Not checked:</span> <strong>${fmt(missed)}</strong>` : '');
  if (!missed) return `<div class="hint mb-8" data-cve-covered="">${head}</div>`;
  const reasons = c.reasons && typeof c.reasons === 'object' ? c.reasons : {};
  const byReason = Object.keys(_CVE_NOT_CHECKED).filter(r => num(reasons[r]) > 0).map(r =>
    `<tr><td>${escHtml(label(r))}</td><td class="ta-center">${fmt(reasons[r])}</td></tr>`).join('');
  const rows = (Array.isArray(c.packages) ? c.packages : []).slice(0, 200).map(p => !p || typeof p.name !== 'string' ? ''
    : `<tr><td class="mono-12" data-no-i18n="">${escHtml(p.name)}</td><td class="mono-12" data-no-i18n="">${escHtml(typeof p.version === 'string' ? p.version : '')}</td><td>${escHtml(label(p.reason))}</td></tr>`).join('');
  const more = num(c.more) > 0 ? `<div class="hint mt-6"><span>Packages not shown:</span> <span>${fmt(c.more)}</span></div>` : '';
  return `<details class="mb-8" data-cve-covered=""><summary class="hint pointer">${head}</summary>`
    + (byReason ? `<div class="scrollable-table-wrap audit-scroll mt-6"><table><thead><tr><th>Reason</th><th class="ta-center">Count</th></tr></thead><tbody>${byReason}</tbody></table></div>` : '')
    + (rows ? `<div class="scrollable-table-wrap audit-scroll mt-6"><table><thead><tr><th>Package</th><th>Installed</th><th>Reason</th></tr></thead><tbody>${rows}</tbody></table></div>` : '')
    + more + '</details>';
}

// What a host with no finding says. "No vulnerabilities found" is a statement about the whole host, and is only
// made when every package was checked.
function _cveNoneFoundHtml(data) {
  const c = data && data.covered && typeof data.covered === 'object' ? data.covered : null;
  const num = v => typeof v === 'number' && isFinite(v) && v > 0 ? Math.floor(v) : 0;
  const missed = c ? num(c.not_checked) : 0, checked = c ? num(c.checked) : 0;
  if (missed && checked) {
    return `<div class="empty-state" data-cve-none-found=""><span>None found in the packages that could be checked:</span> <strong>${checked.toLocaleString(_localeTag())}</strong></div>`;
  }
  if (missed) return '<div class="empty-state" data-cve-none-found=""><span>None found, but none of the packages could be checked.</span></div>';
  return '<div class="empty-state">No vulnerabilities found.</div>';
}

// 8.0.2: which kernel a host runs, as its last scan matched it (cve_scanner.kernel_state), and when it could not
// tell, why. A finding of the kernel is held against the package that kernel is, and a finding an installed kernel
// that is not running would clear says "reboot to apply". The sentences are translated; a release and a package
// are data.
const _CVE_KERNEL_WHY = {
  not_reported: 'The agent of this host does not report its running kernel.',
  no_images: 'The agent found no installed kernel package.',
  no_owner: 'No installed kernel package owns the files of the running kernel.',
  several_owners: 'More than one installed package owns the running kernel, and they are built from different versions.',
  not_in_list: 'The package that owns the running kernel is not in the package list the host sent.',
};

function _cveKernelHtml(k) {
  if (!k || typeof k !== 'object' || (k.state !== 'matched' && k.state !== 'unknown')) return '';
  const txt = v => typeof v === 'string' ? v : '';
  const data = v => `<span class="mono-12" data-no-i18n="">${escHtml(txt(v))}</span>`;
  const running = txt(k.running) ? data(k.running) : '<span>not reported</span>';
  if (k.state === 'unknown') {
    const why = Object.prototype.hasOwnProperty.call(_CVE_KERNEL_WHY, k.why) ? ` <span>${escHtml(_CVE_KERNEL_WHY[k.why])}</span>` : '';
    return `<div class="hint mb-8" data-cve-kernel="unknown"><span>Running kernel:</span> ${running} <span>It could not be matched to an installed package, so findings against the kernel are matched against every installed kernel.</span>${why}</div>`;
  }
  const left = typeof k.left_out === 'number' && isFinite(k.left_out) && k.left_out > 0 ? Math.floor(k.left_out) : 0;
  return `<div class="hint mb-8" data-cve-kernel="matched"><span>Running kernel:</span> ${running} · <span>Package:</span> ${data(txt(k.package) + ' ' + txt(k.version))}`
    + (txt(k.newer) ? ` · <span>Installed, not running:</span> ${data(k.newer)} <span>Reboot to start it.</span>` : '')
    + (left ? ` · <span>Packages of other installed kernels, not counted:</span> <span>${left.toLocaleString(_localeTag())}</span>` : '')
    + '</div>';
}

// 8.0.1: a finding is filed under the source package; this names the installed packages it covers.
function _cveBinariesHtml(f) {
  if (!Array.isArray(f.binaries) || !f.binaries.length) return '';
  const more = Number(f.binaries_more) > 0 ? ` +${Number(f.binaries_more)}` : '';
  return ` <span class="hint" data-cve-binaries=""><span>installed as</span> <span class="mono-12" data-no-i18n="">${escHtml(f.binaries.join(', '))}${more}</span></span>`;
}

async function openDeviceCVE(devId, devName) {
  document.getElementById('cve-detail-title').textContent = `CVE Findings: ${devName}`;
  document.getElementById('cve-detail-body').innerHTML = _skeletonBlock(6);
  openModal('cve-detail-modal');
  const data = await api('GET', `/devices/${devId}/cve`);
  // A refusal (404 deleted device, 403 out-of-scope / other tenant) resolves
  // with {error} and NO findings array — the old `if (!data) return` let it
  // through and `data.findings.length` threw mid-template, leaving the modal
  // stuck on its skeleton. `error` alone is not the marker: it is a legal 200
  // field (the scanner's own note, rendered inline below).
  if (!data || !Array.isArray(data.findings)) {
    _errorState('cve-detail-body', () => openDeviceCVE(devId, devName),
      {msg: (data && data.error) || 'Could not load CVE findings for this host.'});
    return;
  }
  const sevColor = {critical: 'var(--red)', high: 'var(--orange)', medium: 'var(--amber)', low: 'var(--muted)', unknown: 'var(--muted)'};
  let html = `<div class="sysinfo-row mb-16"><div class="sysinfo-pill"><div class="label">Ecosystem</div><div class="value fs-12">${escHtml(data.ecosystem)}</div></div><div class="sysinfo-pill"><div class="label">Packages</div><div class="value">${data.packages_count}</div></div><div class="sysinfo-pill"><div class="label">Last scan</div><div class="value fs-11">${timeAgoHtml(data.scanned_at, {empty: 'never'})}</div></div><div class="sysinfo-pill"><div class="label">Findings</div><div class="value">${data.findings.length}</div></div></div>`;
  // the list of a Windows or macOS host is sent for the software views and is not compared with OSV: the tip must not say it is
  const _sendTip = data.coverage === 'no_matcher'
    ? 'Ask the agent to send the software installed on this host now'
    : 'Ask the agent to send its full installed-package list now — the CVE scanner compares this against OSV';
  html += `<div class="mb-14 row-6"><button class="btn-icon isl-387" data-action-btn="_forcePackageScanBtn" data-dev-id="${escAttr(devId)}" data-dev-name="${escAttr(devName)}" title="${escAttr(_sendTip)}">${_icon('refresh',14)} Send package list now</button><button class="btn-icon" data-action-btn="_sbomDeviceBtn" data-dev-id="${escAttr(devId)}" data-fmt="cyclonedx" title="Download a CycloneDX SBOM (with CVE findings) for this host">${_icon('download',14)} SBOM (CycloneDX)</button><button class="btn-icon" data-action-btn="_sbomDeviceBtn" data-dev-id="${escAttr(devId)}" data-fmt="spdx" title="Download an SPDX 2.3 SBOM for this host">${_icon('download',14)} SBOM (SPDX)</button><button class="btn-icon" data-action="sbomCaptureBaseline" data-arg="${escAttr(devId)}" title="Snapshot the current package set as the SBOM diff baseline">${_icon('copy',14)} Baseline</button><button class="btn-icon" data-action="sbomShowDiff" data-arg="${escAttr(devId)}" data-arg2="${escAttr(devName)}" title="Show package changes since the captured baseline">${_icon('list',14)} Changes since baseline</button>${_cveAcceptButtons(data.accepted, devId, devName)}</div>`;
  html += _cveAcceptedHtml(data.accepted);
  if (data.error) html += `<div class="isl-388">${escHtml(data.error)}</div>`;
  html += _cveCoverageHtml(data);
  const roll = _cveRollupHtml(data.rollup);
  html += roll;
  html += _cveKernelHtml(data.kernel);            // 8.0.2: which kernel the host runs, and how the scan matched it
  html += _cveCoveredHtml(data.covered);          // 8.0.2: which packages were checked, and why not the others
  if (!data.findings.length) { if (!roll && data.coverage !== 'no_matcher') html += _cveNoneFoundHtml(data); }
  else {
    // v3.14.0: surface exploited-in-wild + high-EPSS first.
    const _sevRank = {critical: 4, high: 3, medium: 2, low: 1, unknown: 0};
    data.findings.sort((a, b) =>
      (b.kev ? 1 : 0) - (a.kev ? 1 : 0)
      || (_sevRank[b.severity] || 0) - (_sevRank[a.severity] || 0)
      || (b.epss || 0) - (a.epss || 0));
    const _fixShown = cveFixFilter ? data.findings.filter(f => _cveFixKey(f) === cveFixFilter) : data.findings;
    if (cveFixFilter) {
      html += `<div class="hint mb-8"><span>${escHtml(_CVE_FIX_NAME[cveFixFilter] || '')}</span> <span>${_fixShown.length} / ${data.findings.length}</span> <button class="btn-icon cell-sm" data-action="clearCveFixFilter" data-arg="${escAttr(devId)}" data-arg2="${escAttr(devName)}">Show all</button></div>`;
    }
    html += _fixShown.map(f => {
      const color = sevColor[f.severity] || 'var(--muted)';
      const refsHtml = (f.refs||[]).slice(0,2).map(r => { try { const u = new URL(r); if (u.protocol !== 'http:' && u.protocol !== 'https:') return ''; return `<a href="${escHtml(r)}" target="_blank" rel="noopener noreferrer" class="c-accent">${escHtml(u.hostname)}</a>`; } catch(e) { return ''; } }).filter(Boolean).join('');
      const aliasesHtml = (f.aliases||[]).map(a => `<code class="isl-389">${escHtml(a)}</code>`).join('');
      return `<div class="isl-390 ${f.ignored?'is-ignored':''}"><div class="isl-391"><div><span class="isl-392" data-color="${escAttr(color)}">${escHtml(f.severity)}</span><code class="isl-393" data-copy="" title="Click to copy">${escHtml(f.vuln_id)}</code>${f.kev ? '<span class="kev-badge" title="Actively exploited in the wild (CISA KEV)">KEV</span>' : ''}${f.epss ? `<span class="epss-chip" title="EPSS — probability of exploitation in the next 30 days">EPSS ${(f.epss*100).toFixed(f.epss>=0.1?0:1)}%</span>` : ''}${f.ignored ? '<span class="isl-394">(ignored: '+escHtml(f.ignore_reason||'')+')</span>' : ''}${f.new ? '<span class="status-pill warn">New</span>' : ''}</div><div class="isl-395">${escHtml(f.published || '')}</div></div><div class="isl-396"><strong data-no-i18n="">${escHtml(f.package)}</strong> <span class="c-muted">${escHtml(f.version)}</span>${_cveBinariesHtml(f)}${_cveFixHtml(f)}</div>${f.summary ? `<div class="hint-mb6">${escHtml(f.summary)}</div>` : ''}<div class="isl-397">${aliasesHtml}${refsHtml}<button class="btn-icon isl-398" data-action="aiTriageCve" data-arg="${escAttr(f.vuln_id)}" data-arg2="${escAttr(f.package)}" data-arg3="${escAttr(f.version)}" data-arg4="${escAttr(devName)}" data-arg5="${escAttr(f.summary||'')}">${_icon('sparkles',14)} Triage</button>${!f.ignored ? `<button class="btn-icon isl-399" data-action="ignoreCVE" data-arg="${escAttr(f.vuln_id)}" data-arg2="${escAttr(devId)}" data-arg3="${escAttr(devName)}" >Ignore</button>` : ''}</div></div>`;
    }).join('');
  }
  document.getElementById('cve-detail-body').innerHTML = html;
}

// 8.0.2: a host can be accepted as it is (POST /devices/{id}/cve/accept): its findings stop counting, and a finding that comes after is marked New and counts.
function _cveAcceptButtons(accepted, devId, devName) {
  const who = `data-arg="${escAttr(devId)}" data-arg2="${escAttr(devName)}"`;
  if (!accepted) return `<button class="btn-icon" data-action="cveAcceptHost" ${who}>${_icon('check',14)} Accept host</button>`;
  return `<button class="btn-icon" data-action="cveAcceptNew" ${who}>${_icon('check',14)} Accept what is new</button><button class="btn-icon" data-action="cveUnacceptHost" ${who}>Stop accepting</button>`;
}

function _cveAcceptedHtml(a) {
  if (!a || typeof a !== 'object' || Array.isArray(a)) return '';
  const n = (typeof a.n === 'number' && isFinite(a.n) && a.n >= 0) ? Math.floor(a.n) : 0;
  const by = typeof a.by === 'string' && a.by ? ` · <span class="hint">by</span> <span data-no-i18n>${escHtml(a.by)}</span>` : '';
  const why = typeof a.reason === 'string' && a.reason ? `<div class="hint mt-6"><span>Reason</span>: <span data-no-i18n>${escHtml(a.reason)}</span></div>` : '';
  const when = typeof a.at === 'number' ? ` ${timeAgoHtml(a.at)}` : '';
  return `<div class="mb-14"><strong>Host accepted</strong>${when}${by}${why}<div class="hint mt-6"><span>Accepted findings:</span> <strong>${escHtml(String(n))}</strong> · <span>A finding that came after is marked New and counts.</span></div></div>`;
}

let _cveAcceptCtx = null;

function cveAcceptHost(devId, devName) {
  _cveAcceptCtx = {devId, devName};
  document.getElementById('cve-accept-host').textContent = devName;
  document.getElementById('cve-accept-reason').value = '';
  openModal('cve-accept-modal');
}

async function _cveAcceptPost(devId, devName, body, done) {
  const r = await api('POST', `/devices/${encodeURIComponent(devId)}/cve/${done}`, body);
  if (!r || r.error) { failToast(r); return false; }
  openDeviceCVE(devId, devName);
  loadCVEReport();
  return true;
}

async function _confirmCveAccept() {
  if (!_cveAcceptCtx) return;
  const {devId, devName} = _cveAcceptCtx;
  const reason = document.getElementById('cve-accept-reason').value.trim();
  if (await _cveAcceptPost(devId, devName, {reason}, 'accept')) {
    closeModal('cve-accept-modal');
    toast('Host accepted', 'success');
  }
}

// accept again what the host has now: the findings that came after, with the time and the reason of the first acceptance kept
async function cveAcceptNew(devId, devName) {
  if (await _cveAcceptPost(devId, devName, {}, 'accept')) toast('Host accepted', 'success');
}

async function cveUnacceptHost(devId, devName) {
  if (!await uiConfirm('Stop accepting this host? Its findings will count again.')) return;
  await _cveAcceptPost(devId, devName, {}, 'unaccept');
}

function ignoreCVE(vulnId, devId, devName) {
  _cveIgnoreCtx = {vulnId, devId, devName};
  document.getElementById('cve-ignore-vuln').textContent = vulnId;
  document.getElementById('cve-ignore-reason').value = '';
  const dev = document.querySelector('input[name="cve-ignore-scope"][value="device"]');
  if (dev) dev.checked = true;
  openModal('cve-ignore-modal');
}

async function _confirmCveIgnore() {
  if (!_cveIgnoreCtx) return;
  const {vulnId, devId, devName} = _cveIgnoreCtx;
  const reason = document.getElementById('cve-ignore-reason').value.trim();
  const scopeSel = document.querySelector('input[name="cve-ignore-scope"]:checked');
  const scope = (scopeSel && scopeSel.value === 'global') ? 'global' : devId;
  // Busy state comes from the dispatcher's _btnInflight — the button carries
  // data-action="_confirmCveIgnore", so disabling it here suppressed the
  // spinner + aria-busy + completion pulse.
  try {
    const result = await api('POST', '/cve/ignore', {vuln_id: vulnId, reason, scope});
    if (result && result.ok) {
      closeModal('cve-ignore-modal');
      toast(`${vulnId} ignored (${scope === 'global' ? 'fleet-wide' : 'this host'})`, 'success');
      openDeviceCVE(devId, devName);
      loadCVEReport();
    }
  } catch (e) {
    toast('Ignore failed: ' + (e.message || String(e)), 'error');
  }
}

function aiTriageCve(cveId, packageName, version, deviceName, description) {
  openAIModal({
    title:    `Triage ${cveId}`,
    system:   'triage_cve',
    userMsg:  `CVE: ${cveId}\nHost: ${deviceName}\nAffected package: ${packageName} ${version}\n\nDescription:\n${description || '(no description available — assess based on the CVE ID alone)'}`,
    context:  `cve:${cveId}`,
    maxTokens: 1000,
  });
}

async function unignoreCVE(vulnId) {
  if (!await uiConfirm(`Stop ignoring ${vulnId}? It will count as a finding again.`)) return;
  const r = await api('DELETE', '/cve/ignore/' + encodeURIComponent(vulnId)).catch(() => null);
  if (r && r.ok) { toast(`No longer ignoring ${vulnId}`, 'success'); loadIgnoredItems(); }
  else toast((r && r.error) || 'Failed to remove ignore', 'error');
}

function _cveScanBtn(btn) {
  triggerCVEScan(btn.dataset.devId || undefined, btn);
}

async function cveRealert() {
  if (!await uiConfirm('Re-raise alerts for the current CVE backlog? This fires cve_found '
    + 'now for every host with critical/high findings (already-known CVEs don\'t '
    + 're-alert on their own).')) return;
  const r = await api('POST', '/cve/realert', {});
  if (r && r.ok) {
    toast(`Re-alerted ${plural(r.devices, 'host', 'hosts')}`, 'success');
    refreshAlertsBadge();
  } else failToast(r);
}
